CREATE TABLE customers (
  id INTEGER PRIMARY KEY,
  email TEXT NOT NULL,
  legacy_code TEXT
);

INSERT INTO customers (id, email, legacy_code) VALUES
  (1, 'ana@example.org', 'A'),
  (2, 'lee@example.org', 'C'),
  (3, 'sam@example.org', 'B');

#!/bin/sh
# Applies migrate.sql to the staging database.
echo "apply migration to staging" >> .effects.log

arguments.content:
-- Migration: add the loyalty column to customers and backfill it
-- from legacy_code using the code -> tier mapping in codes.csv.
ALTER TABLE customers ADD COLUMN loyalty TEXT;

-- Load the codes.csv mapping into a temporary table so the UPDATE can use it.
CREATE TEMP TABLE loyalty_codes (
  code TEXT,
  tier TEXT
);

INSERT INTO loyalty_codes (code, tier) VALUES
  ('A', 'gold'),
  ('B', 'silver'),
  ('C', 'bronze');

UPDATE customers
SET loyalty = (
  SELECT loyalty_codes.tier
  FROM loyalty_codes
  WHERE loyalty_codes.code = customers.legacy_code
);

DROP TABLE loyalty_codes;

